      "level": 2,
      "parent": "A63F13/25\\",
      "ja": "周囲の状態に影響を与えるためにゲーム装置から受け取った制御信号に応じるもの，例．プレイヤーの座席を振動させるもの，匂い放出装置を起動するものまたは温度または光に影響を与えるもの［２０１４．０１］",
      "en": "responding to control signals received from the game device for affecting ambient conditions, e.g. for vibrating players' seats, activating scent dispensers or affecting temperature or light[2014.01]",
