      "code": "A63F13/352\\",
      "level": 3,
      "parent": "A63F13/35\\",
      "ja": "特殊なゲームサーバ装置に関するもの，例．国別サーバまたはゲーム空間の区画を管理する複数のサーバに接続される地域サーバ［２０１４．０１］",
      "en": "involving special game server arrangements, e.g. regional servers connected to a national server or a plurality of servers managing partitions of the game world",
