    "A63F13/355\\": {
      "code": "A63F13/355\\",
      "level": 3,
      "parent": "A63F13/35\\",
      "ja": "処理能力に制限のあるクライアントに代わって処理を行うためのもの，例．サーバがゲームシーンをエンコードされた動画ストリームに変換して携帯電話または能力の低いクライアントへ送信するもの［２０１４．０１］",
      "en": "Performing operations on behalf of clients with restricted processing capabilities, e.g. servers transform changing game scene into an encoded video stream for transmitting to a mobile phone or a thin client [2014.01]",
      "count": 169,
      "ipcCode": "A63F13/355",
      "fTerm": "2C001",
      "childFlag": 3,
      "sourceFile": "fi_A63F.txt",
      "kind": "fi"
    },
