      "code": "A63F13/358\\",
      "level": 3,
      "parent": "A63F13/35\\",
      "ja": "ネットワークまたはサーバの負荷にゲームの進行を適合させるもの，例．クライアント間の接続速度によるレイテンシーを減少させるもの［２０１４．０１］",
      "en": "Adapting the game course according to the network or server load, e.g. for reducing latency due to different connection speeds between clients",
      "count": 273,
      "ipcCode": "A63F13/358",
      "fTerm": "2C001",
      "childFlag": 3,
      "sourceFile": "fi_A63F.txt",
      "kind": "fi"
