      "ja": "ビデオゲーム装置の入力制御信号の処理，例．プレイヤーにより生成された信号または環境に由来する信号［２０１４．０１］",
      "en": "Processing input control signals of video game devices, e.g. signals generated by the player or derived from the environment",
