      "level": 2,
      "parent": "A63F13/40\\",
      "ja": "入力信号をゲームコマンドに対応付けることによるもの，例．タッチスクリーン上のスタイラスから仮想車両のステアリング角への変換の対応付け［２０１４．０１］",
      "en": "by mapping the input signals into game commands, e.g. mapping the displacement of a stylus on a touch screen to the steering angle of a virtual vehicle",
