      "level": 3,
      "parent": "A63F13/42\\",
      "ja": "プレイヤーをアシストすることを目的として自動的に行われるもの，例．ドライビングゲームの自動ブレーキ［２０１４．０１］",
      "en": "automatically for the purpose of assisting the player, e.g. automatic braking in a driving game",
