      "ja": "音響入力信号に関するもの，例．ピッチまたはリズムの抽出結果を使うものまたは音声認識を使うもの［２０１４．０１］",
      "en": "involving acoustic input signals, e.g. by using the results of pitch or rhythm extraction or voice recognition",
