      "code": "A63F13/54\\",
      "level": 2,
      "parent": "A63F13/50\\",
      "ja": "音響信号に関するもの，例．ドライビングゲームで回転数に依存するエンジン音を模擬するものまたは仮想的な壁での反響を模擬するもの［２０１４．０１］",
      "en": "involving acoustic signals, e.g. for simulating revolutions per minute [RPM] dependent engine sounds in a driving game or reverberation against a virtual wall",
      "count": 2480,
