      "parent": "A63F13/55\\",
      "ja": "ゲームキャラクターの状態の計算，例．スタミナ，強さ，モチベーションまたは体力［２０１４．０１］",
      "en": "by computing conditions of game characters, e.g. stamina, strength, motivation or energy level",
